func TestSubscriberOnboardDryRunResolvesTagNamesByPlaceholder(t *testing.T) {
	calls := subscriberOnboardDryRunCalls(
		"reader@example.com",
		map[string]any{"email_address": "reader@example.com"},
		[]string{"welcome", "123"},
		[]string{"456"},
	)
	if len(calls) != 5 {
		t.Fatalf("calls len = %d, want 5: %#v", len(calls), calls)
	}
	if calls[1].Method != "GET" || calls[1].Path != "/v4/tags" {
		t.Fatalf("tag-name dry-run did not include pagination resolution call: %#v", calls[1])
	}
	if calls[2].Path != "/v4/tags/{resolved_tag_id}/subscribers" {
		t.Fatalf("tag-name path = %q, want resolved-id placeholder", calls[2].Path)
	}
	if calls[2].Note == "" {
		t.Fatal("tag-name call missing resolution note")
	}
	if calls[3].Path != "/v4/tags/123/subscribers" {
		t.Fatalf("numeric tag path = %q, want concrete id path", calls[3].Path)
	}
	if calls[4].Path != "/v4/sequences/456/subscribers" {
		t.Fatalf("sequence path = %q, want sequence subscription call", calls[4].Path)
	}
}
